<?php require __DIR__.'/../app/bootstrap.php';admin_required();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$o=$s->fetch();if(!$o){http_response_code(404);exit('Order not found');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$allowed=['pending','confirmed','processing','shipped','delivered','cancelled'];$status=$_POST['status']??'';$pay=['unpaid','paid','refunded'];$payment=$_POST['payment_status']??'';if(!in_array($status,$allowed,true)||!in_array($payment,$pay,true))$error='Invalid status selected.';else{$s=db()->prepare('UPDATE orders SET status=?,payment_status=? WHERE id=?');$s->execute([$status,$payment,$id]);header('Location: '.url('admin/order-view.php?id='.$id.'&saved=1'));exit;}}$s=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$id]);$items=$s->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order <?=e($o['order_number'])?></title><link rel="stylesheet" href="<?=e(url('assets/css/style.css'))?>"></head><body class="admin-body"><aside class="admin-sidebar"><a class="wordmark" href="<?=e(url('admin/index.php'))?>"><span>NEXT</span> <b>TECH</b></a><a href="<?=e(url('admin/index.php'))?>">Dashboard</a><a href="<?=e(url('admin/products.php'))?>">Products</a><a href="<?=e(url('admin/orders.php'))?>">Orders</a><a href="<?=e(url('admin/logout.php'))?>">Logout</a></aside><main class="admin-main"><div class="admin-top"><h1><?=e($o['order_number'])?></h1></div><?php if($error):?><p class="form-error"><?=e($error)?></p><?php endif;?><?php if(isset($_GET['saved'])):?><p class="success-message">Order updated.</p><?php endif;?><section class="admin-panel"><h2>Customer & Delivery</h2><p><b><?=e($o['customer_name'])?></b> · <?=e($o['phone'])?></p><p><?=e($o['address'])?>, <?=e($o['city'])?></p><p>Note: <?=e($o['note']?:'—')?></p></section><section class="admin-panel table-wrap" style="margin-top:18px"><h2>Items</h2><table><thead><tr><th>Product</th><th>Unit Price</th><th>Qty</th><th>Total</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['product_name'])?></td><td><?=money($it['unit_price'])?></td><td><?=(int)$it['quantity']?></td><td><?=money($it['line_total'])?></td></tr><?php endforeach;?></tbody></table><h3>Order Total: <?=money($o['total'])?></h3></section><form class="admin-panel form-grid" method="post" style="margin-top:18px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Order Status<select name="status"><?php foreach(['pending','confirmed','processing','shipped','delivered','cancelled'] as $v):?><option value="<?=$v?>" <?=$o['status']===$v?'selected':''?>><?=ucfirst(str_replace('_',' ',$v))?></option><?php endforeach;?></select></label><label>Payment Status<select name="payment_status"><?php foreach(['unpaid','paid','refunded'] as $v):?><option value="<?=$v?>" <?=$o['payment_status']===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select></label><div class="full"><button class="btn btn-primary">Save Order Update</button></div></form></main></body></html>